  #= points =# [
    SVector{ 3, T }((
      parse(T, "0.00000000000000000000000000000000e+00"),
      parse(T, "0.00000000000000000000000000000000e+00"),
      parse(T, "-5.00000000000000000000000000000000e-01"), )),
  ],
  #= weights =# T[
    parse(T, "2.66666666666666651863693004997913e+00"),
  ])
end

